#!/bin/shset -eecho "⏳ Waiting for MySQL database..."until nc -z -v -w30 "$DB_HOST" "$DB_PORT"; do  echo "Waiting for database connection at $DB_HOST:$DB_PORT..."  sleep 2doneecho "✅ Database is reachable!"echo "🔄 Running database migrations..."npm run db:migrate || trueecho "🌱 Running database seed (initial data)..."npm run db:seed || trueecho "🚀 Starting Nova Industrial API Server..."exec node dist/server.js